/**
 * SDF pill sprites for the price-pill symbol layer (generated; do not edit by hand).
 * Alpha holds a signed distance field, so one white shape can be tinted per land type with
 * `icon-color` and outlined with `icon-halo-*`. 3x texels, 26pt tall, 4pt halo room.
 */

export const PILL_HEIGHT = 26;
export const PILL_PAD = 4;
export const PILL_WIDTHS = [44, 52, 60, 68, 76, 88, 100] as const;

const uris: Record<string, string> = {
  'lc-pill-44': 'data:image/png;base64,',
  'lc-pill-52': 'data:image/png;base64,',
  'lc-pill-60': 'data:image/png;base64,',
  'lc-pill-68': 'data:image/png;base64,',
  'lc-pill-76': 'data:image/png;base64,',
  'lc-pill-88': 'data:image/png;base64,',
  'lc-pill-100': 'data:image/png;base64,',
};

/** Ready for MapLibre `<Images images={...} />`. */
export const pillImages = Object.fromEntries(
  Object.entries(uris).map(([name, uri]) => [name, { source: { uri, scale: 3 }, sdf: true }]),
);
